<script setup lang="ts">
import UserPicker from '../UserPicker.vue'
import { useVaultSwitcher } from '../../composables/useVaultSwitcher'

const selection = defineModel<string>({ default: 'all' })
const { selectedPerson,inviteRole,permissionRole,roleOptions,vaultRoleLabel,canManage,canEditMember,inviteMode, inviteCategories, permissionMember, permissionMode, permissionCategories, permissionOptions, categoryOptions, editPermissions, savePermissions, permissionLabel, mediaError, svgImageUrl, selectedSvg, uploadGroupSvg, removeGroupSvg, uploadPersonalSvg, removePersonalSvg, vault, personalOpen, personalName, personalLabel, managePersonal, renamePersonal, renameName, rename, shared, auth, open, managedId, managed, label, name, removing, select, manage, create, invite, revoke } = useVaultSwitcher(selection)
</script>
<template>
  <button class="workspace-switch" @click="open = true"><span class="workspace-avatar"><img v-if="selectedSvg" :src="svgImageUrl(selectedSvg)" class="category-custom-icon" alt=""/><UIcon v-else :name="selection === 'personal' ? 'i-lucide-user-round' : 'i-lucide-vault'" /></span><span><strong>{{ label }}</strong><small>{{ selection === 'personal' ? 'Только для вас' : 'Личные и общие карточки' }}</small></span><UIcon name="i-lucide-chevrons-up-down" /></button>
  <UModal v-model:open="open" title="Хранилища" description="Выберите хранилище или создайте общее для своей команды.">
    <template #body>
      <div class="space-y-2">
        <button class="vault-choice" :aria-pressed="selection === 'all'" @click="select('all')"><UIcon name="i-lucide-layout-grid" /><span><strong>Все хранилища</strong><small>Все доступные карточки на главной</small></span></button>
        <div class="flex items-center gap-2"><button class="vault-choice flex-1" :aria-pressed="selection === 'personal'" @click="select('personal')"><img v-if="vault.data.svg" :src="svgImageUrl(vault.data.svg)" class="category-custom-icon" alt=""/><UIcon v-else name="i-lucide-user-round" /><span><strong>{{ personalLabel }}</strong><small>Доступно только вам</small></span></button><UButton icon="i-lucide-pencil" color="neutral" variant="ghost" aria-label="Переименовать личное хранилище" @click="managePersonal" /></div>
        <div v-for="group in shared.groups" :key="group.id" class="flex items-center gap-2"><button class="vault-choice flex-1" :aria-pressed="selection === group.id" @click="select(group.id)"><img v-if="group.data.svg" :src="svgImageUrl(group.data.svg)" class="category-custom-icon" alt=""/><UIcon v-else name="i-lucide-users" /><span><strong>{{ group.name }}</strong><small>{{ group.members.length }} участников · {{ group.ownerId === auth.user?.id ? 'Вы владелец' : 'Общее хранилище' }}</small></span></button><UButton icon="i-lucide-settings-2" color="neutral" variant="ghost" :aria-label="`Участники: ${group.name}`" @click="manage(group.id)" /></div>
      </div>
      <UButton class="mt-4" size="sm" variant="ghost" icon="i-lucide-refresh-cw" label="Обновить хранилища" :loading="shared.loading" :disabled="shared.busy" @click="shared.refresh(true)" />
      <form class="mt-6 space-y-3 border-t border-default pt-5" @submit.prevent="create"><UFormField label="Новое общее хранилище" required><UInput v-model="name" class="w-full" placeholder="Например, Команда маркетинга" :maxlength="80" required /></UFormField><UButton type="submit" icon="i-lucide-plus" label="Создать хранилище" :loading="shared.busy" :disabled="shared.loading || !name.trim()" /></form>
      <UAlert v-if="shared.error" class="mt-4" color="error" :description="shared.error" />
    </template>
  </UModal>
  <UModal :open="!!managedId" :title="managed?.name || 'Общее хранилище'" description="Доступ участника можно ограничить выбранными категориями." @update:open="value => { if (!value) managedId = null }">
    <template #body>
      <template v-if="managed"><section v-if="canManage" class="group-svg-editor"><label class="media-upload-label">SVG хранилища<input type="file" accept="image/svg+xml,.svg" :disabled="shared.busy" @change="uploadGroupSvg"/></label><div v-if="managed.data.svg" class="flex items-center gap-3 mt-3"><img :src="svgImageUrl(managed.data.svg)" class="category-upload-preview" alt="Иконка хранилища"/><UButton variant="outline" color="neutral" size="xs" label="Убрать SVG" :disabled="shared.busy" @click="removeGroupSvg"/></div><UAlert v-if="mediaError" class="mt-3" color="error" :description="mediaError"/></section><form v-if="canManage" class="mb-5 space-y-3" @submit.prevent="rename"><UFormField label="Название хранилища" required><UInput v-model="renameName" class="w-full" :maxlength="80" required /></UFormField><UButton type="submit" label="Переименовать" icon="i-lucide-pencil" variant="soft" :loading="shared.busy" :disabled="shared.loading || !renameName.trim() || renameName.trim() === managed.name" /></form>
        <div v-for="member in managed.members" :key="member.userId" class="shared-member"><span class="min-w-0"><NuxtLink :to="`/password/team/${member.userId}`" class="block truncate font-semibold">{{ member.fullName||member.email }}</NuxtLink><small>{{ member.brand === 'light' ? 'Light' : 'Magnat' }} · {{ member.userId === managed.ownerId ? 'Владелец' : vaultRoleLabel(member.role) }} · {{ permissionLabel(member) }}</small></span><UButton v-if="canEditMember(member)" color="neutral" variant="ghost" icon="i-lucide-settings-2" :aria-label="`Права: ${member.email}`" :disabled="shared.busy" @click="editPermissions(member)"/><UButton v-if="canEditMember(member)" color="error" variant="ghost" icon="i-lucide-user-minus" :aria-label="`Отозвать доступ: ${member.email}`" :disabled="shared.busy" @click="removing = member.userId" /></div>
        <form v-if="canManage" class="mt-6 space-y-3" @submit.prevent="invite"><UFormField label="Участник" required><UserPicker v-model="selectedPerson" :disabled="shared.busy"/></UFormField><UFormField label="Роль в хранилище"><USelect v-model="inviteRole" :items="roleOptions" class="w-full"/></UFormField><UFormField v-if="inviteRole!=='manager'" label="Доступ к категориям"><USelect v-model="inviteMode" :items="permissionOptions" class="w-full"/></UFormField><UFormField v-if="inviteRole!=='manager'&&inviteMode==='selected'" label="Разрешённые категории"><USelectMenu v-model="inviteCategories" :items="categoryOptions" value-key="value" multiple class="w-full" placeholder="Выберите категории"/></UFormField><p class="text-xs leading-5 text-slate-500">Пользователь должен быть зарегистрирован. Доступ действует сразу и не зависит от бренда аккаунта или присутствия владельца онлайн.</p><UButton type="submit" label="Дать доступ" icon="i-lucide-user-plus" :loading="shared.busy" :disabled="shared.loading || !selectedPerson || inviteRole!=='manager'&&inviteMode==='selected'&&!inviteCategories.length" /></form>
        <UAlert v-if="shared.error" class="mt-4" color="error" :description="shared.error" />
      </template>
    </template>
  </UModal>
  <UModal :open="!!permissionMember" title="Роль и доступ к категориям" description="Если карточка относится к нескольким категориям, достаточно доступа к одной из них. Категории без папки также выбираются отдельно." @update:open="value=>{if(!value)permissionMember=null}"><template #body><div class="space-y-4"><p class="text-sm text-slate-500">{{ permissionMember?.email }}</p><UFormField label="Роль участника"><USelect v-model="permissionRole" :items="roleOptions" class="w-full"/></UFormField><UFormField v-if="permissionRole!=='manager'" label="Режим доступа"><USelect v-model="permissionMode" :items="permissionOptions" class="w-full"/></UFormField><UFormField v-if="permissionRole!=='manager'&&permissionMode==='selected'" label="Разрешённые категории"><USelectMenu v-model="permissionCategories" :items="categoryOptions" value-key="value" multiple class="w-full" placeholder="Выберите категории"/></UFormField><p class="text-xs leading-5 text-slate-500">При полном доступе новые категории доступны автоматически. При выборе отдельных категорий доступ к новым выдаётся отдельно. Папки не меняют права доступа.</p><UAlert v-if="shared.error" color="error" :description="shared.error"/></div></template><template #footer><UButton color="neutral" variant="outline" label="Отмена" :disabled="shared.busy" @click="permissionMember=null"/><UButton label="Сохранить доступ" :loading="shared.busy" @click="savePermissions"/></template></UModal>
  <UModal v-model:open="personalOpen" title="Название личного хранилища" description="Название изменится только в вашем аккаунте."><template #body><form class="space-y-4" @submit.prevent="renamePersonal"><label class="media-upload-label">SVG хранилища<input type="file" accept="image/svg+xml,.svg" @change="uploadPersonalSvg"/></label><div v-if="vault.data.svg" class="flex items-center gap-3"><img :src="svgImageUrl(vault.data.svg)" class="category-upload-preview" alt="Иконка хранилища"/><UButton type="button" variant="outline" color="neutral" size="xs" label="Убрать SVG" @click="removePersonalSvg"/></div><UAlert v-if="mediaError" color="error" :description="mediaError"/><UFormField label="Название" required><UInput v-model="personalName" class="w-full" :maxlength="80" required /></UFormField><UAlert v-if="vault.error" color="error" :description="vault.error" /><UButton type="submit" label="Сохранить название" :loading="vault.busy" /></form></template></UModal>
  <UModal :open="!!removing" title="Отозвать доступ?" description="Участник больше не сможет открывать это хранилище или изменять его пароли." @update:open="value => { if (!value) removing = null }"><template #body><UAlert v-if="shared.error" color="error" :description="shared.error" /></template><template #footer><UButton color="neutral" variant="outline" label="Отмена" @click="removing = null" /><UButton color="error" label="Отозвать доступ" :loading="shared.busy" @click="revoke" /></template></UModal>
</template>
